233	     * {@code householdId}) with different telephones have distinct identity keys and are both
234	     * allowed; only an exact full-key match is a duplicate. The telephone and email components are
235	     * already held in their normalized forms (canonical E.164 and lower-cased) on every write path,
236	     * so the key is comparable across owners. Not persisted: it is computed from the current fields.
237	     */
238	    @Transient
239	    public String getIdentityKey() {
240	        String telephoneOrEmpty = this.telephone == null ? "" : this.telephone;
241	        String emailOrEmpty = this.email == null ? "" : this.email;
242	        String householdOrEmpty = this.householdId == null ? "" : this.householdId;
243	        return telephoneOrEmpty + "|" + emailOrEmpty + "|" + householdOrEmpty;
