283	    /**
284	     * Return the Pet with the given name, or null if none found for this Owner.
285	     *
286	     * @param name to test
287	     * @return true if pet name is already in use
288	     */
289	    public Pet getPet(String name) {
290	        return getPet(name, false);
291	    }
292	
293	    /**
294	     * Return the Pet with the given name, or null if none found for this Owner.
295	     *
296	     * @param name to test
297	     * @return true if pet name is already in use
298	     */
299	    public Pet getPet(String name, boolean ignoreNew) {
300	        name = name.toLowerCase();
301	        for (Pet pet : getPetsInternal()) {
302	            if (!ignoreNew || !pet.isNew()) {
303	                String compName = pet.getName();
304	                compName = compName.toLowerCase();
305	                if (compName.equals(name)) {
306	                    return pet;
307	                }
308	            }
309	        }
310	        return null;
311	    }
312	
313	    public Pet getPet(Integer petId) {
314	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
315	    }
