319	        return new ToStringCreator(this)
320	
321	            .append("id", this.getId())
322	            .append("new", this.isNew())
323	            .append("lastName", this.getLastName())
324	            .append("firstName", this.getFirstName())
325	            .append("address", this.address)
326	            .append("city", this.city)
327	            .append("telephone", this.telephone)
328	            .toString();
