36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.samples.petclinic.util.AddressValidator;
42	import org.springframework.samples.petclinic.util.DisposableEmailValidator;
43	import org.springframework.samples.petclinic.util.PostcodeValidator;
44	import org.springframework.samples.petclinic.util.RegistrationDateValidator;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
105	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
106	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        AddressValidator.validate(owner.getAddress());
115	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
116	        DisposableEmailValidator.validate(owner.getEmail());
117	        RegistrationDateValidator.validate(owner.getRegistrationDate());
118	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
119	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
120	        }
121	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
122	        // and postcode are automatically the same household.
123	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
124	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
125	        // A second owner in an existing household is a duplicate unless it declares itself a member,
126	        // which bypasses the household duplicate block.
127	        if (!sharesHousehold && this.clinicService.isHouseholdInUse(owner)) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        // Reject exact identity duplicates: when the new owner's whole identity key
131	        // (telephone|email|householdId) matches an existing one.
132	        if (this.clinicService.isIdentityKeyInUse(owner)) {
133	            return new ResponseEntity<>(HttpStatus.CONFLICT);
134	        }
135	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        this.clinicService.saveOwner(owner, sharesHousehold);
139	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
140	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
141	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
