31	
32	/**
33	 * Mostly used as a facade so all controllers have a single point of entry
34	 *
35	 * @author Michael Isvy
36	 * @author Vitaliy Fedoriv
37	 */
38	public interface ClinicService {
39	
40		Pet findPetById(int id) throws DataAccessException;
41		Collection<Pet> findAllPets() throws DataAccessException;
42	    Page<Pet> findPets(Pageable pageable) throws DataAccessException;
43		void savePet(Pet pet) throws DataAccessException;
44		void deletePet(Pet pet) throws DataAccessException;
45	
46		Collection<Visit> findVisitsByPetId(int petId);
47		Visit findVisitById(int visitId) throws DataAccessException;
48		Collection<Visit> findAllVisits() throws DataAccessException;
49		void saveVisit(Visit visit) throws DataAccessException;
50		void deleteVisit(Visit visit) throws DataAccessException;
51		Vet findVetById(int id) throws DataAccessException;
52		Collection<Vet> findVets() throws DataAccessException;
53		Collection<Vet> findAllVets() throws DataAccessException;
54		void saveVet(Vet vet) throws DataAccessException;
55		void deleteVet(Vet vet) throws DataAccessException;
56		Owner findOwnerById(int id) throws DataAccessException;
57		Collection<Owner> findAllOwners() throws DataAccessException;
58		Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException;
59		void saveOwner(Owner owner) throws DataAccessException;
60	
61		/**
62		 * Saves the given owner, additionally recording whether it was created as a <em>declared</em>
63		 * household member (via {@code sharesHousehold}). A declared member is explicitly not treated as a
64		 * suspected duplicate of the existing household it joins, so its {@code possibleDuplicate} flag is
65		 * left clear; otherwise duplicate detection runs as normal. Equivalent to
66		 * {@link #saveOwner(Owner)} with {@code declaredHouseholdMember = false}.
67		 *
68		 * @param owner the owner to save
69		 * @param declaredHouseholdMember whether the owner declared itself a member of an existing household
70		 */
71		void saveOwner(Owner owner, boolean declaredHouseholdMember) throws DataAccessException;
72	
73		void deleteOwner(Owner owner) throws DataAccessException;
74	
75		/**
76		 * Returns {@code true} if the given owner's derived identity key equals that of another owner,
77		 * i.e. the create would introduce a duplicate. The identity key
78		 * ({@link Owner#getIdentityKey()}) is {@code normalizedTelephone + '|' + (email or empty) + '|' +
79		 * (householdId or empty)} and is the single, consolidated criterion for duplicate detection:
80		 * only an exact whole-key match counts. Because the telephone is part of the key, two members of
81		 * the same household (same {@code householdId}) with different telephones have distinct keys and
82		 * are both allowed. Enforces the "no duplicate identity key" invariant on owner creation.
83		 *
84		 * @param owner the (not yet persisted) owner whose identity key to check
85		 * @return whether an existing owner already has the same identity key
86		 */
87		boolean isIdentityKeyInUse(Owner owner) throws DataAccessException;
88	
89		/**
90		 * Returns {@code true} if another owner already belongs to the same household as the given
91		 * (not yet persisted) owner, i.e. an existing owner has the identical computed
92		 * {@link #householdIdFor household id}. Because the household is keyed on (last name, postcode),
93		 * this holds exactly when an existing owner shares the new owner's last name and postcode, making
94		 * the new owner a household duplicate. The create endpoint rejects such an owner with 409 unless
95		 * it declares itself a household member ({@code sharesHousehold}).
96		 *
97		 * @param owner the (not yet persisted) owner whose household to check
98		 * @return whether an existing owner already belongs to the same household
99		 */
100		boolean isHouseholdInUse(Owner owner) throws DataAccessException;
101	
102		/**
103		 * Returns a deterministic, shared household identifier derived from the given last name and
104		 * postcode: the first 12 hexadecimal characters of the SHA-256 digest over
105		 * {@code normalizedLastName + '|' + postcode}. The last name is normalized (trimmed, runs of
106		 * whitespace collapsed, lower-cased) before hashing, so every owner with the same last name and
107		 * postcode deterministically receives the identical value and therefore shares a household
108		 * automatically. This household id also forms the final component of each owner's identity key.
109		 *
110		 * @param lastName the last name of the household
111		 * @param postcode the postcode of the household
112		 * @return a stable identifier shared by all owners of the household
113		 */
114		String householdIdFor(String lastName, String postcode) throws DataAccessException;
115	
116		/**
117		 * Returns {@code true} if the given city has already reached its owner capacity, i.e. it already
118		 * contains 50 or more owners (compared case-insensitively, the same way the per-city customer-code
119		 * sequence counts them). Enforces the "at most 50 owners per city" invariant on owner creation.
120		 *
121		 * @param city the city to check
122		 * @return whether the city already contains 50 or more owners
123		 */
124		boolean isCityAtCapacity(String city) throws DataAccessException;
125	
126		/**
127		 * Returns {@code true} if 100 or more owners have already been registered today, i.e. the number
128		 * of owners whose {@code registrationDate} equals the server's current date has reached the daily
129		 * create limit. Enforces the "at most 100 owners created per day" invariant on owner creation.
130		 *
131		 * @return whether 100 or more owners already carry today's registration date
132		 */
133		boolean isDailyRegistrationAtCapacity() throws DataAccessException;
134	
135		/**
136		 * Returns {@code true} when more than 80 owners have already been created today, i.e. the
137		 * number of owners whose {@code registrationDate} equals the server's current date exceeds
138		 * the bulk-signup threshold. Drives the read-only {@code bulkSignupWarning} response flag.
139		 *
140		 * @return whether more than 80 owners already carry today's registration date
141		 */
142		boolean isBulkSignupDay() throws DataAccessException;
143	
144		Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException;
145	
146		PetType findPetTypeById(int petTypeId);
147		Collection<PetType> findAllPetTypes() throws DataAccessException;
148		Collection<PetType> findPetTypes() throws DataAccessException;
149		void savePetType(PetType petType) throws DataAccessException;
150		void deletePetType(PetType petType) throws DataAccessException;
151		Specialty findSpecialtyById(int specialtyId);
152		Collection<Specialty> findAllSpecialties() throws DataAccessException;
153		void saveSpecialty(Specialty specialty) throws DataAccessException;
154		void deleteSpecialty(Specialty specialty) throws DataAccessException;
155	
156	    List<Specialty> findSpecialtiesByNameIn(Set<String> names) throws DataAccessException;
157	}
