256	    @Override
257	    @Transactional
258	    public void saveOwner(Owner owner, boolean declaredHouseholdMember) throws DataAccessException {
259	        if (owner.isNew()) {
260	            LocalDate effectiveDate = owner.getRegistrationDate() != null
261	                ? owner.getRegistrationDate()
262	                : LocalDate.now();
263	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
264	            if (owner.getHouseholdId() == null) {
265	                owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
266	            }
267	            if (owner.getCustomerCode() == null) {
268	                owner.setCustomerCode(generateCustomerCode(owner));
269	            }
270	            if (owner.getNamesakeCount() == null) {
271	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
272	            }
273	            if (owner.getPossibleDuplicate() == null) {
274	                // A declared household member is not a suspected duplicate; otherwise flag it against
275	                // any existing member of the same household it collides with.
276	                Integer possibleDuplicateOf = declaredHouseholdMember ? null : findPossibleDuplicateOf(owner);
277	                owner.setPossibleDuplicateOf(possibleDuplicateOf);
278	                owner.setPossibleDuplicate(possibleDuplicateOf != null);
279	            }
280	        }
281	        ownerRepository.save(owner);
282	        decorateWithHouseholdMemberCount(owner);
283	    }
284	
285	    /**
286	     * Count the existing owners (before this create) that share the given first and last name,
287	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
288	     */
289	    private int countNamesakes(String firstName, String lastName) {
290	        if (firstName == null || lastName == null) {
291	            return 0;
292	        }
293	        return (int) ownerRepository.findAll().stream()
294	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
295	                && lastName.equalsIgnoreCase(owner.getLastName()))
296	            .count();
297	    }
298	
299	    /**
300	     * Build a customer code formatted {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
301	     * canonical region derived from the owner's postcode (falling back to the city-to-region
302	     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}) and {@code HASH8}
303	     * is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the owner's
304	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}).
305	     * <p>
306	     * If the computed code collides with an existing owner's {@code customerCode}, it is
307	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
308	     * makes it unique (e.g. {@code 'NSW-1A2B3C4D-2'}).
309	     */
310	    private String generateCustomerCode(Owner owner) {
311	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
312	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
313	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
314	        String base = region + "-" + Sha256Hex.upperHexPrefix(telephone + lastName, 8);
315	
316	        Set<String> existingCodes = ownerRepository.findAll().stream()
317	            .map(Owner::getCustomerCode)
318	            .filter(Objects::nonNull)
319	            .collect(Collectors.toSet());
320	        if (!existingCodes.contains(base)) {
321	            return base;
322	        }
323	        int n = 2;
324	        while (existingCodes.contains(base + "-" + n)) {
325	            n++;
326	        }
327	        return base + "-" + n;
328	    }
329	
330	    /**
331	     * Count the existing owners whose city matches the given city, compared case-insensitively,
332	     * used by the per-city capacity rule ({@link #isCityAtCapacity}).
333	     */
334	    private long countOwnersInCity(String city) {
335	        if (city == null) {
336	            return 0L;
337	        }
338	        return ownerRepository.findAll().stream()
339	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
340	            .count();
341	    }
342	
343	    @Override
344	    @Transactional(readOnly = true)
345	    public boolean isCityAtCapacity(String city) throws DataAccessException {
346	        return countOwnersInCity(city) >= CITY_CAPACITY;
347	    }
348	
349	    @Override
350	    @Transactional(readOnly = true)
351	    public boolean isDailyRegistrationAtCapacity() throws DataAccessException {
352	        return countRegisteredToday() >= DAILY_CAPACITY;
353	    }
354	
355	    @Override
356	    @Transactional(readOnly = true)
357	    public boolean isBulkSignupDay() throws DataAccessException {
358	        return countRegisteredToday() > BULK_SIGNUP_THRESHOLD;
359	    }
360	
361	    /**
362	     * Count the owners whose registration date equals today's business day, used by the
363	     * daily create-limit and bulk-signup rules.
364	     */
365	    private long countRegisteredToday() {
366	        LocalDate businessDay = toBusinessDay(LocalDate.now());
367	        return ownerRepository.findAll().stream()
368	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
369	            .count();
370	    }
371	
372	    /**
373	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced
374	     * to the following Monday, while a weekday is returned unchanged. Applied to the effective
375	     * registration date (whether supplied or defaulted to the server date) so that the stored
376	     * {@code registrationDate}, every value derived from it (such as the membership number's year
377	     * segment) and the per-day create-limit all use the adjusted business day.
378	     */
379	    private static LocalDate toBusinessDay(LocalDate date) {
380	        DayOfWeek day = date.getDayOfWeek();
381	        if (day == DayOfWeek.SATURDAY) {
382	            return date.plusDays(2);
383	        }
384	        if (day == DayOfWeek.SUNDAY) {
385	            return date.plusDays(1);
386	        }
387	        return date;
388	    }
389	
390	    @Override
391	    @Transactional(readOnly = true)
392	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
393	        String identityKey = owner.getIdentityKey();
394	        return ownerRepository.findAll().stream()
395	            .filter(existing -> existing != owner)
396	            .map(Owner::getIdentityKey)
397	            .anyMatch(identityKey::equals);
398	    }
399	
400	    /**
401	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
402	     * duplicate of, or {@code null} when there is none. A possible duplicate belongs to an existing
403	     * owner's household (same computed {@code householdId}, i.e. same last name and postcode) while
404	     * carrying a different telephone, so it is not a hard duplicate (its identity key is unique) but is
405	     * worth flagging. When several existing owners match, the one with the lowest id is returned so the
406	     * result is deterministic. Computed once, at creation, to drive the read-only
407	     * {@code possibleDuplicate}/{@code possibleDuplicateOf} fields.
408	     */
409	    private Integer findPossibleDuplicateOf(Owner owner) {
410	        String householdId = owner.getHouseholdId();
411	        if (householdId == null) {
412	            return null;
413	        }
414	        return ownerRepository.findAll().stream()
415	            .filter(existing -> existing != owner && existing.getId() != null)
416	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
417	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
418	            .map(Owner::getId)
419	            .min(Integer::compareTo)
420	            .orElse(null);
421	    }
422	
423	    @Override
424	    @Transactional(readOnly = true)
425	    public boolean isHouseholdInUse(Owner owner) throws DataAccessException {
426	        String householdId = owner.getHouseholdId() != null
427	            ? owner.getHouseholdId()
428	            : householdIdFor(owner.getLastName(), owner.getPostcode());
429	        return ownerRepository.findAll().stream()
430	            .filter(existing -> existing != owner && existing.getId() != null)
431	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
432	    }
433	
434	    @Override
435	    @Transactional(readOnly = true)
436	    public String householdIdFor(String lastName, String postcode) throws DataAccessException {
437	        String key = normalizeHouseholdValue(lastName) + "|" + (postcode == null ? "" : postcode);
438	        return Sha256Hex.upperHexPrefix(key, 12);
439	    }
440	
441	    /**
442	     * Normalizes a household field (the last name) for duplicate comparison by trimming,
443	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
444	     * spaced but equivalent values compare equal.
445	     */
446	    private static String normalizeHouseholdValue(String value) {
447	        if (value == null) {
448	            return "";
449	        }
450	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
451	    }
452	
453	    /**
454	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
455	     * owners that share its {@code householdId}. Owners without a household id are left at a count
456	     * of zero.
457	     *
458	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
459	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
460	     */
461	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
462	        if (!owners.isEmpty()) {
463	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
464	                .filter(owner -> owner.getHouseholdId() != null)
465	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
466	            for (Owner owner : owners) {
467	                long size = owner.getHouseholdId() == null
468	                    ? 0L
469	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
470	                owner.setHouseholdMemberCount((int) size);
471	            }
472	        }
473	        return result;
474	    }
475	
476	    /**
477	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
478	     */
479	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
480	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
481	    }
482	
483	    @Override
484	    @Transactional(readOnly = true)
485	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
486	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
